ur teacher.", "targetId": "etf26.p4.math", "evidenceRole": "exit", "xp": 10, "workshop": {"taskLabel": "Save your individual evidence", "purpose": "One short response connects your calculation and plan interpretation to the notebook. The teacher observes measuring and building separately."}, "sei": {"visualBlockId": "mvp-etf-4-11-explain", "frames": [{"level": 1, "text": "The plan shows ___. I used ___ to calculate ___. My answer is ___ (units). My notebook page is ___."}, {"level": 2, "text": "My reference is ___. I checked ___ by ___. The test supports ___, with the limit ___."}], "wordBank": ["dimension", "datum", "units", "calculate", "inspect", "revision"], "talkFirst": false}}]}}]$etf_data$::jsonb; begin if (select count(*) from jsonb_array_elements(expected) j join lessons l on l.id=(j->>'id')::uuid where to_jsonb(l) @> j) <> 11 then raise exception 'Stored lesson content does not match authored source'; end if; end $check$;
do $vocab$ declare data jsonb := $etf_data$[{"lesson_id": "b5d5d2c4-0492-5dfb-8c49-7575e99abd24", "lesson_slug": "mvp-etf-4-01", "name": "ETF P4 · 01 · Build a Detector That Does Something", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "circuit", "tier": 3, "category": "electrical", "definition": "An arrangement of connected electrical components; sustained current requires a complete conducting path through a source and load.", "example": "Trace a complete path from one source terminal through the switch and lamp to the other terminal.", "order_index": 0, "difficulty": "medium"}, {"term": "switch", "tier": 3, "category": "electrical", "definition": "A component that opens or closes a conducting path in a circuit.", "example": "Place the switch so opening it interrupts the intended lamp path.", "order_index": 1, "difficulty": "medium"}, {"term": "closed circuit", "tier": 3, "category": "electrical", "definition": "A circuit with a complete conducting path through the source and load.", "example": "With the switch closed and every connection complete, the source and lamp form a closed path.", "order_index": 2, "difficulty": "medium"}, {"term": "open circuit", "tier": 3, "category": "electrical", "definition": "A circuit with a break that prevents sustained current through that path.", "example": "When the switch opens, the break stops sustained current through the lamp path.", "order_index": 3, "difficulty": "medium"}, {"term": "polarity", "definition": "The positive and negative orientation of electrical terminals or components.", "tier": 3, "category": "project-language", "example": "Connect the protected LED using the polarity markings required by its classroom kit.", "order_index": 4, "difficulty": "medium"}, {"term": "route", "tier": 3, "category": "layout", "definition": "The planned path followed by a service, material, or moving object.", "example": "Draw the two dry model service paths before constructing their crossing.", "order_index": 5, "difficulty": "medium"}, {"term": "allowance", "tier": 3, "category": "layout", "definition": "An amount deliberately included for a stated purpose, such as overlap, cutting loss, or material thickness.", "example": "Include both 3/4-in wall allowances when recalculating each blank dimension.", "order_index": 6, "difficulty": "medium"}, {"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "8e65aedf-96f5-5583-87f1-44bb30f707d5", "lesson_slug": "mvp-etf-4-02", "name": "ETF P4 · 02 · Read the Schematic and Fix the Trigger", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 0, "difficulty": "medium"}, {"term": "layout", "tier": 3, "category": "layout", "definition": "The planned or marked positions of parts, edges, and reference lines before making or placing something.", "example": "Lay out the work area's boundaries and fixture locations before placing the paper equipment.", "order_index": 1, "difficulty": "medium"}, {"term": "trial", "tier": 2, "category": "investigation", "definition": "One run of a test using a recorded set of conditions.", "example": "Record each run and identify whether it used a fresh specimen or a previously loaded one.", "order_index": 2, "difficulty": "medium"}, {"term": "fault", "tier": 3, "category": "electrical", "definition": "A condition that prevents a system from operating as intended.", "example": "An open switch or a broken lead can prevent the model lamp from operating.", "order_index": 3, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 4, "difficulty": "medium"}, {"term": "switch", "tier": 3, "category": "electrical", "definition": "A component that opens or closes a conducting path in a circuit.", "example": "Place the switch so opening it interrupts the intended lamp path.", "order_index": 5, "difficulty": "medium"}, {"term": "enclosure", "tier": 3, "category": "fabrication", "definition": "A surrounding structure that contains or protects parts of a system.", "example": "Build a paper base and four walls around the proposed low-voltage service route.", "order_index": 6, "difficulty": "medium"}, {"term": "access", "tier": 3, "category": "design", "definition": "The space or opening needed to reach a part for operation, inspection, or maintenance.", "example": "Demonstrate that the chosen opening lets a person reach the model component without tearing the enclosure.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "c368f58a-21b0-598a-a4fa-ba846df69404", "lesson_slug": "mvp-etf-4-03", "name": "ETF P4 · 03 · Measure Voltage to Find an Open Path", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "voltage", "tier": 3, "category": "electrical", "definition": "Electric potential difference: energy transferred per unit charge between two points, measured in volts (V).", "example": "The supplied resistor example has 6 V across its load.", "order_index": 0, "difficulty": "medium"}, {"term": "test point", "tier": 3, "category": "electrical", "definition": "A specified location in a circuit where an observation or measurement is made.", "example": "State which two locations an approved voltage measurement would compare.", "order_index": 1, "difficulty": "medium"}, {"term": "rating", "tier": 3, "category": "electrical", "definition": "A stated operating value or limit for a component, valid under specified conditions.", "example": "Label the supplied voltage and current values as stated operating data rather than student measurements.", "order_index": 2, "difficulty": "medium"}, {"term": "measured value", "tier": 2, "category": "measurement", "definition": "A number with a unit obtained from a stated measurement method.", "example": "Record the actual tape reading of 40 3/8 in before judging whether it passes.", "order_index": 3, "difficulty": "medium"}, {"term": "open circuit", "tier": 3, "category": "electrical", "definition": "A circuit with a break that prevents sustained current through that path.", "example": "When the switch opens, the break stops sustained current through the lamp path.", "order_index": 4, "difficulty": "medium"}, {"term": "diagnosis", "tier": 3, "category": "inspection", "definition": "Identifying a problem's cause by following evidence from inspection and tests.", "example": "Follow a recorded sequence of inspection and approved tests to identify which condition caused the failure.", "order_index": 5, "difficulty": "medium"}, {"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 6, "difficulty": "medium"}, {"term": "uncertainty", "tier": 2, "category": "measurement", "definition": "The doubt or range associated with a measurement because tools and methods cannot give an exact value.", "example": "Identify how reaction time or a hard-to-read volume mark affects confidence in the rate.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "0b7ff29a-a638-5630-b720-cb889cdf244c", "lesson_slug": "mvp-etf-4-04", "name": "ETF P4 · 04 · Measure Current and Use a Circuit Model", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "current", "tier": 3, "category": "electrical", "definition": "The rate of flow of electric charge, measured in amperes (A).", "example": "The model calculation predicts 0.20 A through a 30-Ω resistor at 6 V.", "order_index": 0, "difficulty": "medium"}, {"term": "series circuit", "tier": 3, "category": "electrical", "definition": "A circuit arrangement with components along one path, so the same current passes through each component.", "example": "Two supplied 12-Ω resistors in one path have an equivalent resistance of 24 Ω.", "order_index": 1, "difficulty": "medium"}, {"term": "Ohm's law", "tier": 3, "category": "electrical", "definition": "The relationship V = I × R for an ohmic component under constant physical conditions such as temperature.", "example": "Use I = V/R to calculate 6 V / 30 Ω = 0.20 A for the supplied resistor case.", "order_index": 2, "difficulty": "medium"}, {"term": "resistance", "tier": 3, "category": "electrical", "definition": "A measure of opposition to current, expressed in ohms (Ω); for a resistor model, R = V ÷ I.", "example": "The supplied 30-Ω resistor model is not a claim that a real warming lamp has constant resistance.", "order_index": 3, "difficulty": "medium"}, {"term": "voltage", "tier": 3, "category": "electrical", "definition": "Electric potential difference: energy transferred per unit charge between two points, measured in volts (V).", "example": "The supplied resistor example has 6 V across its load.", "order_index": 4, "difficulty": "medium"}, {"term": "unit conversion", "tier": 2, "category": "math", "definition": "Expressing the same quantity in another unit without changing its size.", "example": "Convert 3 ft 4 in to 40 in before adding it to another length in inches.", "order_index": 5, "difficulty": "medium"}, {"term": "rating", "tier": 3, "category": "electrical", "definition": "A stated operating value or limit for a component, valid under specified conditions.", "example": "Label the supplied voltage and current values as stated operating data rather than student measurements.", "order_index": 6, "difficulty": "medium"}, {"term": "test point", "tier": 3, "category": "electrical", "definition": "A specified location in a circuit where an observation or measurement is made.", "example": "State which two locations an approved voltage measurement would compare.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "bd1d6573-8d2a-532e-82ad-7aac0e05ecad", "lesson_slug": "mvp-etf-4-05", "name": "ETF P4 · 05 · Wire Two Rooms with Independent Controls", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "parallel circuit", "tier": 3, "category": "electrical", "definition": "A circuit arrangement with branches connected across the same two points, so each branch has the same voltage across it.", "example": "Two resistor branches connected across the same 6-V source each have 6 V across them.", "order_index": 0, "difficulty": "medium"}, {"term": "branch", "tier": 3, "category": "electrical", "definition": "One path for current between junctions in a circuit.", "example": "Trace each complete path separately in the parallel drawing.", "order_index": 1, "difficulty": "medium"}, {"term": "switch", "tier": 3, "category": "electrical", "definition": "A component that opens or closes a conducting path in a circuit.", "example": "Place the switch so opening it interrupts the intended lamp path.", "order_index": 2, "difficulty": "medium"}, {"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 3, "difficulty": "medium"}, {"term": "layout", "tier": 3, "category": "layout", "definition": "The planned or marked positions of parts, edges, and reference lines before making or placing something.", "example": "Lay out the work area's boundaries and fixture locations before placing the paper equipment.", "order_index": 4, "difficulty": "medium"}, {"term": "route", "tier": 3, "category": "layout", "definition": "The planned path followed by a service, material, or moving object.", "example": "Draw the two dry model service paths before constructing their crossing.", "order_index": 5, "difficulty": "medium"}, {"term": "allowance", "tier": 3, "category": "layout", "definition": "An amount deliberately included for a stated purpose, such as overlap, cutting loss, or material thickness.", "example": "Include both 3/4-in wall allowances when recalculating each blank dimension.", "order_index": 6, "difficulty": "medium"}, {"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "39950b2c-7d82-51e9-9398-6f7fc4b9c347", "lesson_slug": "mvp-etf-4-06", "name": "ETF P4 · 06 · Add a Useful Control Feature", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "power", "tier": 3, "category": "electrical", "definition": "The rate at which energy is transferred or converted, measured in watts (W).", "example": "A supplied 6-V load drawing 0.25 A converts energy at 6 × 0.25 = 1.5 W.", "order_index": 0, "difficulty": "medium"}, {"term": "current", "tier": 3, "category": "electrical", "definition": "The rate of flow of electric charge, measured in amperes (A).", "example": "The model calculation predicts 0.20 A through a 30-Ω resistor at 6 V.", "order_index": 1, "difficulty": "medium"}, {"term": "voltage", "tier": 3, "category": "electrical", "definition": "Electric potential difference: energy transferred per unit charge between two points, measured in volts (V).", "example": "The supplied resistor example has 6 V across its load.", "order_index": 2, "difficulty": "medium"}, {"term": "rating", "tier": 3, "category": "electrical", "definition": "A stated operating value or limit for a component, valid under specified conditions.", "example": "Label the supplied voltage and current values as stated operating data rather than student measurements.", "order_index": 3, "difficulty": "medium"}, {"term": "access", "tier": 3, "category": "design", "definition": "The space or opening needed to reach a part for operation, inspection, or maintenance.", "example": "Demonstrate that the chosen opening lets a person reach the model component without tearing the enclosure.", "order_index": 4, "difficulty": "medium"}, {"term": "enclosure", "tier": 3, "category": "fabrication", "definition": "A surrounding structure that contains or protects parts of a system.", "example": "Build a paper base and four walls around the proposed low-voltage service route.", "order_index": 5, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 6, "difficulty": "medium"}, {"term": "test plan", "tier": 3, "category": "inspection", "definition": "A written method that states what to test, the conditions, what to record, and how to judge the result.", "example": "Name the access and fit checks, plus a future operating test if electrical hardware is unavailable.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "8a541873-1c64-5d12-8024-183d316f3061", "lesson_slug": "mvp-etf-4-07", "name": "ETF P4 · 07 · Budget Energy for the Working System", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "power", "tier": 3, "category": "electrical", "definition": "The rate at which energy is transferred or converted, measured in watts (W).", "example": "A supplied 6-V load drawing 0.25 A converts energy at 6 × 0.25 = 1.5 W.", "order_index": 0, "difficulty": "medium"}, {"term": "energy", "tier": 3, "category": "electrical", "definition": "An amount transferred or converted by a system; electrical use may be counted in joules, watt-hours, or kilowatt-hours.", "example": "Using the 1.5-W load for 2 h transfers 3 Wh of energy.", "order_index": 1, "difficulty": "medium"}, {"term": "watt", "tier": 3, "category": "math", "definition": "The unit of power, written W; one watt equals one joule per second.", "example": "Label 1.5 W as power, not as the total energy used during the session.", "order_index": 2, "difficulty": "medium"}, {"term": "watt-hour", "tier": 3, "category": "math", "definition": "The energy transferred by one watt operating for one hour; written Wh.", "example": "Multiply watts by hours: 1.5 W × 2 h = 3 Wh.", "order_index": 3, "difficulty": "medium"}, {"term": "kilowatt-hour", "tier": 3, "category": "math", "definition": "An energy unit equal to 1,000 watt-hours, written kWh.", "example": "Divide 3 Wh by 1,000 to obtain 0.003 kWh.", "order_index": 4, "difficulty": "medium"}, {"term": "operating time", "tier": 3, "category": "math", "definition": "The duration for which a device is in use under the stated conditions.", "example": "Reducing the hours used reduces the energy estimate when the power stays the same.", "order_index": 5, "difficulty": "medium"}, {"term": "tariff", "tier": 3, "category": "estimating", "definition": "A stated price schedule; a classroom electricity calculation may use a fictional price per kWh.", "example": "At the fictional $0.20/kWh rate, 0.003 kWh costs $0.0006 for energy alone.", "order_index": 6, "difficulty": "medium"}, {"term": "assumption", "tier": 2, "category": "design", "definition": "A condition treated as true for planning or calculation that must be stated and checked when possible.", "example": "State the model's assumption that the panel sizes tile the surface without cutting loss.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "c4b154ba-d452-5d7a-bec5-989605a6f5ce", "lesson_slug": "mvp-etf-4-08", "name": "ETF P4 · 08 · Fault-Find and Hand Over the Controls", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "fault", "tier": 3, "category": "electrical", "definition": "A condition that prevents a system from operating as intended.", "example": "An open switch or a broken lead can prevent the model lamp from operating.", "order_index": 0, "difficulty": "medium"}, {"term": "diagnosis", "tier": 3, "category": "inspection", "definition": "Identifying a problem's cause by following evidence from inspection and tests.", "example": "Follow a recorded sequence of inspection and approved tests to identify which condition caused the failure.", "order_index": 1, "difficulty": "medium"}, {"term": "hypothesis", "tier": 2, "category": "investigation", "definition": "A testable proposed explanation for an observation or problem.", "example": "Predict that the lead is disconnected, then name an observation that would support or reject that explanation.", "order_index": 2, "difficulty": "medium"}, {"term": "repair", "tier": 3, "category": "fabrication", "definition": "A correction intended to restore a part or system to its required operation.", "example": "After securing the loose actuator mount, repeat the same three-cycle test to check the repair.", "order_index": 3, "difficulty": "medium"}, {"term": "retest", "tier": 2, "category": "investigation", "definition": "A new test after a change, using stated conditions so the results can be compared.", "example": "Test the revised wrap under the original conditions and report an inconclusive result honestly if necessary.", "order_index": 4, "difficulty": "medium"}, {"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 5, "difficulty": "medium"}, {"term": "handover", "tier": 3, "category": "communication", "definition": "The transfer of a completed work package and its essential information to the next person or user.", "example": "Give the next person the brief, drawings, estimate, test record, revisions, and unresolved questions.", "order_index": 6, "difficulty": "medium"}, {"term": "evidence", "tier": 2, "category": "investigation", "definition": "Recorded observations, measurements, or results used to support a claim.", "example": "Record what you actually observed before choosing the next diagnostic action.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "e3587b82-9554-516d-bfd3-00fb16d3b2ca", "lesson_slug": "mvp-etf-4-09", "name": "ETF P4 · 09 · Workshop: Read, Measure, Diagnose", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "template", "tier": 3, "category": "fabrication", "definition": "A pattern used to transfer a shape or feature locations to another piece of material.", "example": "Make a paper pattern another student can use to reproduce the replacement liner.", "order_index": 0, "difficulty": "medium"}, {"term": "datum", "tier": 3, "category": "measurement", "definition": "A chosen reference point, line, or surface from which measurements are taken.", "example": "Name corner A as the datum and locate three school-zone features from it.", "order_index": 1, "difficulty": "medium"}, {"term": "center spacing", "definition": "The distance between the center points or centerlines of two features.", "tier": 3, "category": "project-language", "example": "Two mounting points 3/4 in from opposite edges of an 8 1/2-in plate have 7-in center spacing.", "order_index": 2, "difficulty": "medium"}, {"term": "dimension string", "tier": 3, "category": "drawing", "definition": "A chain of labeled distances between successive features on a drawing.", "example": "Add three consecutive wall segments and compare their sum with the overall wall measurement.", "order_index": 3, "difficulty": "medium"}, {"term": "schematic", "definition": "A drawing that uses symbols to show functional connections rather than exact physical positions.", "tier": 3, "category": "project-language", "example": "The lamp can move across the model room while its electrical connections on the schematic stay the same.", "order_index": 4, "difficulty": "medium"}, {"term": "layout", "tier": 3, "category": "layout", "definition": "The planned or marked positions of parts, edges, and reference lines before making or placing something.", "example": "Lay out the work area's boundaries and fixture locations before placing the paper equipment.", "order_index": 5, "difficulty": "medium"}, {"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 6, "difficulty": "medium"}, {"term": "unit conversion", "tier": 2, "category": "math", "definition": "Expressing the same quantity in another unit without changing its size.", "example": "Convert 3 ft 4 in to 40 in before adding it to another length in inches.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "41eff721-a5d9-5cb2-ba98-6ff96b1b9fbd", "lesson_slug": "mvp-etf-4-10", "name": "ETF P4 · 10 · Prepare a Working Exhibition", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "prototype", "tier": 3, "category": "design", "definition": "A trial version or model used to check a design before committing to a final product.", "example": "Use the paper model to check fit and access before requesting hardware.", "order_index": 0, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 1, "difficulty": "medium"}, {"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 2, "difficulty": "medium"}, {"term": "percent reduction", "tier": 2, "category": "math", "definition": "The decrease divided by the original value, multiplied by 100%.", "example": "A drop reduced from 8°C to 6°C is 2/8 × 100% = 25% smaller than the original drop.", "order_index": 3, "difficulty": "medium"}, {"term": "user need", "tier": 2, "category": "design", "definition": "A practical problem or requirement experienced by the person who will use the result.", "example": "Describe the actual difficulty the school user experiences before suggesting a storage solution.", "order_index": 4, "difficulty": "medium"}, {"term": "evidence", "tier": 2, "category": "investigation", "definition": "Recorded observations, measurements, or results used to support a claim.", "example": "Record what you actually observed before choosing the next diagnostic action.", "order_index": 5, "difficulty": "medium"}, {"term": "handover", "tier": 3, "category": "communication", "definition": "The transfer of a completed work package and its essential information to the next person or user.", "example": "Give the next person the brief, drawings, estimate, test record, revisions, and unresolved questions.", "order_index": 6, "difficulty": "medium"}, {"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "51872d9f-aacb-5725-90e3-11e079952d44", "lesson_slug": "mvp-etf-4-11", "name": "ETF P4 · 11 · Demonstrate, Inspect, and Improve", "unit_id": "trades-etf-4", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p4.vocabulary", "terms": [{"term": "tolerance", "tier": 3, "category": "inspection", "definition": "The allowed variation from a specified dimension or value.", "example": "State the permitted dimensional variation before deciding whether the replacement matches the specification.", "order_index": 0, "difficulty": "medium"}, {"term": "acceptable range", "tier": 2, "category": "inspection", "definition": "The interval of values permitted by the stated limits or tolerance.", "example": "The acceptable interval is 39 3/4 to 40 1/4 in, including the endpoints.", "order_index": 1, "difficulty": "medium"}, {"term": "inspection", "tier": 3, "category": "inspection", "definition": "A deliberate check of the work against its stated requirements.", "example": "Compare the completed model with every acceptance criterion in the plan.", "order_index": 2, "difficulty": "medium"}, {"term": "limitation", "tier": 2, "category": "investigation", "definition": "A boundary on what a method, model, or result can establish.", "example": "Explain which real-system tests were not performed on the paper prototype.", "order_index": 3, "difficulty": "medium"}, {"term": "handover", "tier": 3, "category": "communication", "definition": "The transfer of a completed work package and its essential information to the next person or user.", "example": "Give the next person the brief, drawings, estimate, test record, revisions, and unresolved questions.", "order_index": 4, "difficulty": "medium"}, {"term": "traceability", "tier": 3, "category": "communication", "definition": "The ability to follow a result or decision back to its source measurement, calculation, drawing, or test.", "example": "Show which site measurement and calculation support a dimension in the final drawing.", "order_index": 5, "difficulty": "medium"}, {"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 6, "difficulty": "medium"}, {"term": "reasonableness check", "tier": 2, "category": "math", "definition": "A quick estimate, comparison, or unit check used to see whether a calculated result makes sense.", "example": "The bay width should be slightly less than 6 in because the partitions occupy some of the 18 in.", "order_index": 7, "difficulty": "medium"}]}]$etf_data$::jsonb; item jsonb; saved jsonb; begin for item in select value from jsonb_array_elements(data) loop saved := public.save_lesson_vocabulary((item->>'lesson_id')::uuid,null,item->'terms',false); update public.vocabulary_sets set name=item->>'name',description=item->>'description',created_by='antoccic@fitchburg.k12.ma.us' where id=(saved->>'setId')::uuid; end loop; end $vocab$;
commit; select jsonb_build_object('project',4,'lessons',(select count(*) from lessons where unit_id='trades-etf-4' and not published),'vocabulary_sets',(select count(*) from vocabulary_sets where unit_id='trades-etf-4' and not published),'terms',(select count(*) from vocabulary_terms t join vocabulary_sets s on s.id=t.vocabulary_set_id where s.unit_id='trades-etf-4' and not t.archived));